package dev.sablelife.testing;
import dev.sablelife.SableLife;import dev.sablelife.heart.*;import dev.sablelife.module.*;
import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraft.world.level.block.Blocks;import net.neoforged.neoforge.gametest.*;import java.util.*;
@GameTestHolder("sablelife_defense_tests") @PrefixGameTestTemplate(false)
public final class ArmorRuleGameTests {
 private static HeartBlockEntity core(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4,40,4));l.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());l.setBlockAndUpdate(p.east(),Blocks.IRON_BLOCK.defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p,p.east()),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX()+1,p.getY(),p.getZ()));return (HeartBlockEntity)l.getBlockEntity(b.getPlot().getCenterBlock());}
 @GameTest(template="combat",batch="armor_rules_stage") public static void SignalsChooseLowestRuleAndOuterGateStillApplies(GameTestHelper h){var c=core(h);var a=c.modules().add("armor");a.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.UP)));for(int i=0;i<2;i++){c.wireless().add();c.wireless().channel(i).set(0,1);c.wireless().channel(i).set(6,3);}var r=a.armorRules().add();r.edit("modifier",-50);var r2=a.armorRules().add();r2.edit("channel",2);r2.edit("modifier",50);c.tryActivate(TestActors.creative(h.getLevel()));var hit=c.getBlockPos().east();h.assertTrue(ModuleArmor.damage(c,hit,20)==20,"Empty signal created protection");c.wireless().programOutputs("test",Map.of(0,15));h.assertTrue(ModuleArmor.damage(c,hit,20)==10,"First phase missing");c.wireless().programOutputs("test",Map.of(1,15));h.assertTrue(ModuleArmor.damage(c,hit,20)==30,"Second phase missing");c.wireless().programOutputs("test",Map.of(0,15,1,15));h.assertTrue(ModuleArmor.damage(c,hit,20)==10,"Rows stacked or positive value overrode protection");r.edit("modifier",-100);h.assertTrue(ModuleArmor.damage(c,hit,20)==0,"Immunity failed");r.edit("enabled",0);h.assertTrue(ModuleArmor.damage(c,hit,20)==30,"Disabled row still applied");a.edit("trigger",2,"");a.edit("channel",1,"");c.wireless().programOutputs("test",Map.of(1,15));h.assertTrue(ModuleArmor.damage(c,hit,20)==20,"Outer trigger was ignored");a.edit("trigger",0,"");r2.edit("channel",0);h.assertTrue(ModuleArmor.damage(c,hit,20)==20,"Unbound row applied");h.succeed();}
 @GameTest(template="combat",batch="armor_rule_unpowered") public static void UnpoweredRowsPauseOnSignalAndResumeWithoutBypassingOuterGate(GameTestHelper h){var c=core(h);var a=c.modules().add("armor");a.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.UP)));c.wireless().add();c.wireless().channel(0).set(0,1);c.wireless().channel(0).set(6,3);var r=a.armorRules().add();r.edit("modifier",-100);r.edit("when",1);c.tryActivate(TestActors.creative(h.getLevel()));h.assertTrue(ModuleArmor.damage(c,c.getBlockPos(),20)==0,"Unpowered rule did not apply initially");c.wireless().programOutputs("test",Map.of(0,15));h.assertTrue(ModuleArmor.damage(c,c.getBlockPos(),20)==20,"Powered signal did not pause inverse rule");c.wireless().programOutputs("test",Map.of());h.assertTrue(ModuleArmor.damage(c,c.getBlockPos(),20)==0,"Inverse rule did not resume");r.edit("channel",0);h.assertTrue(ModuleArmor.damage(c,c.getBlockPos(),20)==20,"Unbound inverse rule created immunity");r.edit("channel",2);h.assertTrue(ModuleArmor.damage(c,c.getBlockPos(),20)==20,"Missing channel created immunity");r.edit("channel",1);a.edit("trigger",2,"");a.edit("channel",1,"");h.assertTrue(ModuleArmor.damage(c,c.getBlockPos(),20)==20,"Inverse row bypassed outer trigger");h.assertTrue(VirtualModule.load(a.save()).armorRules().rows().getFirst().when()==1&&!r.edit("when",2),"Condition did not persist or invalid value accepted");h.succeed();}
 @GameTest(template="combat",batch="armor_rules_data") public static void RulesSaveBoundariesAndChannelDeletionAreSafe(GameTestHelper h){var m=new VirtualModule("armor");var r=m.armorRules().add();r.edit("channel",4);r.edit("modifier",1000);r.edit("source",1);h.assertTrue(!r.edit("modifier",Double.NaN)&&!r.edit("modifier",1001)&&!r.edit("source",2)&&!r.edit("channel",1.5),"Invalid rule accepted");var loaded=VirtualModule.load(m.save()).armorRules().rows().getFirst();h.assertTrue(loaded.source()==1&&loaded.channel()==4&&loaded.modifier()==1000,"Save changed rule");h.assertTrue(ModulePreset.create(m.save()).armorRules().rows().getFirst().channel()==0,"Portable preset retained source channel");m.wirelessChannelDeleted(1);h.assertTrue(r.channel()==3,"Deleting earlier channel lost reference");m.wirelessChannelDeleted(2);h.assertTrue(r.channel()==0,"Deleted channel retargeted row");for(int i=1;i<ArmorRules.LIMIT;i++)m.armorRules().add();h.assertTrue(m.armorRules().add()==null,"Rule bound exceeded");var corrupt=m.save();corrupt.getList("ArmorRules",10).getCompound(0).putDouble("Modifier",Double.POSITIVE_INFINITY);h.assertTrue(VirtualModule.load(corrupt).armorRules().rows().size()==ArmorRules.LIMIT-1,"Corrupt row accepted");h.succeed();}
 @GameTest(template="combat",batch="armor_rules_menu") public static void MenuChecksRevisionReadOnlyAndModuleIdentity(GameTestHelper h){var c=core(h);var p=TestActors.creative(h.getLevel());p.setPos(ModuleArena.corePosition(c));var a=c.modules().add("armor");var menu=new ArmorRuleMenu(2,p.getInventory(),c,a,null);h.assertTrue(menu.action(p,c.modules().revision(),new UUID(0,0),"add",0),"Valid add rejected");var row=a.armorRules().rows().getFirst();int revision=c.modules().revision();h.assertTrue(!menu.action(p,revision-1,row.id(),"modifier",-100)&&!menu.action(p,revision,UUID.randomUUID(),"modifier",-100)&&!menu.action(p,revision,row.id(),"modifier",Double.NaN),"Unsafe edit accepted");h.assertTrue(menu.action(p,revision,row.id(),"modifier",-50),"Valid value rejected");c.tryActivate(p);h.assertTrue(!menu.action(p,c.modules().revision(),row.id(),"modifier",-100),"Alive read-only menu edited");h.succeed();}
 @GameTest(template="combat",batch="armor_rules_external") public static void ExternalReceiveUsesNativeWirelessInput(GameTestHelper h){var c=core(h);var a=c.modules().add("armor");a.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.UP)));c.wireless().add();var ch=c.wireless().channel(0);ch.set(0,1);ch.set(6,1);ch.frequency(false,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.NETHER_STAR));var row=a.armorRules().add();row.edit("source",1);row.edit("modifier",-50);c.tryActivate(TestActors.creative(h.getLevel()));c.wireless().tick(h.getLevel());var link=new com.simibubi.create.content.redstone.link.IRedstoneLinkable(){public int getTransmittedStrength(){return 15;}public void setReceivedStrength(int v){}public boolean isListening(){return false;}public boolean isAlive(){return true;}public net.createmod.catnip.data.Couple<com.simibubi.create.content.redstone.link.RedstoneLinkNetworkHandler.Frequency> getNetworkKey(){return net.createmod.catnip.data.Couple.create(com.simibubi.create.content.redstone.link.RedstoneLinkNetworkHandler.Frequency.of(ch.first()),com.simibubi.create.content.redstone.link.RedstoneLinkNetworkHandler.Frequency.of(ch.second()));}public BlockPos getLocation(){return c.getBlockPos();}};com.simibubi.create.Create.REDSTONE_LINK_NETWORK_HANDLER.addToNetwork(h.getLevel(),link);h.assertTrue(c.wireless().input(0)>0&&ModuleArmor.damage(c,c.getBlockPos(),20)==10,"External receiver did not apply rule");row.edit("source",0);h.assertTrue(ModuleArmor.damage(c,c.getBlockPos(),20)==20,"External receive leaked into internal source");com.simibubi.create.Create.REDSTONE_LINK_NETWORK_HANDLER.removeFromNetwork(h.getLevel(),link);h.succeed();}
}
